			owner = {
				has_country_flag = outer_system_mining_stations_constructed
				has_country_flag = birth_of_piracy
			}
		}
	}

	immediate = {
		owner = {
			if = {
				limit = {
					NOT = {
						check_variable = {
							which = outer_system_mining_stations
							value > 0
						}
					}
				}
				set_variable = {
					which = "outer_system_mining_stations"
					value = 1
				}
			}
			else = {
				change_variable = {
					which = "outer_system_mining_stations"
					value = 1
				}
			}
			if = {
				limit = {
					check_variable = {
						which = outer_system_mining_stations
						value > 4
					}
				}
				set_country_flag = outer_system_mining_stations_constructed
